def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            rs = [y for y, x in cells]
            cs = [x for y, x in cells]
            comps.append({
                "color": color,
                "cells": cells,
                "box": (min(rs), min(cs), max(rs), max(cs))
            })

    def inside(a, b):
        # Is box a contained in box b?
        return (a[0] >= b[0] and a[1] >= b[1]
                and a[2] <= b[2] and a[3] <= b[3])

    roots = []
    for i, comp in enumerate(comps):
        box = comp["box"]
        if not any(i != j and inside(box, other["box"]) and box != other["box"]
                   for j, other in enumerate(comps)):
            roots.append(i)

    out = [row[:] for row in grid]
    for root in roots:
        root_box = comps[root]["box"]
        members = [comp for comp in comps if inside(comp["box"], root_box)]
        members.sort(key=lambda comp: (
            (comp["box"][2] - comp["box"][0] + 1) *
            (comp["box"][3] - comp["box"][1] + 1)
        ), reverse=True)

        reversed_colors = [comp["color"] for comp in reversed(members)]
        for comp, new_color in zip(members, reversed_colors):
            for y, x in comp["cells"]:
                out[y][x] = new_color

    return out
